pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/Context.sol";

/**
 * @title TicTacToe
 * @author Your Name
 * @dev A simple, on-chain Tic Tac Toe game for two players.
 */
contract TicTacToe is Context {
    /**
     * @dev Represents the current state of the game.
     * NotStarted: A game has not been initiated.
     * InProgress: The game is active.
     * Player1Won: Player 1 has won.
     * Player2Won: Player 2 has won.
     * Draw: The game ended in a draw.
     */
    enum GameState {
        NotStarted,
        InProgress,
        Player1Won,
        Player2Won,
        Draw
    }

    address public player1; // Player X
    address public player2; // Player O
    address public currentPlayer;
    address public winner;

    GameState public gameState;

    // The game board. 0 = empty, 1 = player1 (X), 2 = player2 (O)
    uint8[3][3] public board;
    uint8 private moveCount;

    event GameStarted(address indexed player1, address indexed player2);
    event MoveMade(address indexed player, uint8 row, uint8 col);
    event GameEnded(GameState result, address winner);
    event GameReset(address indexed resetBy);

    /**
     * @dev Throws if the game is not in the specified state.
     * @param _state The required state for the function to execute.
     */
    modifier onlyInState(GameState _state) {
        require(gameState == _state, "TicTacToe: Invalid game state for this action");
        _;
    }

    /**
     * @dev Throws if the caller is not the current player.
     */
    modifier onlyCurrentPlayer() {
        require(_msgSender() == currentPlayer, "TicTacToe: Not your turn");
        _;
    }

    /**
     * @dev Initializes the contract. The constructor is empty as per requirements.
     */
    constructor() {}

    /**
     * @notice Starts a new game.
     * @dev Sets player1 to the caller and player2 to the provided address.
     * @param _player2 The address of the second player.
     */
    function startGame(address _player2) external onlyInState(GameState.NotStarted) {
        require(_player2 != address(0), "TicTacToe: Player 2 cannot be the zero address");
        require(_msgSender() != _player2, "TicTacToe: Players cannot be the same address");

        player1 = _msgSender();
        player2 = _player2;
        currentPlayer = player1; // Player 1 starts
        gameState = GameState.InProgress;

        emit GameStarted(player1, player2);
    }

    /**
     * @notice Allows the current player to make a move.
     * @param row The row to place the mark (0-2).
     * @param col The column to place the mark (0-2).
     */
    function makeMove(uint8 row, uint8 col) external onlyInState(GameState.InProgress) onlyCurrentPlayer {
        require(row < 3, "TicTacToe: Invalid row");
        require(col < 3, "TicTacToe: Invalid column");
        require(board[row][col] == 0, "TicTacToe: Cell is not empty");

        uint8 playerValue = (currentPlayer == player1) ? 1 : 2;
        board[row][col] = playerValue;
        moveCount++;

        emit MoveMade(currentPlayer, row, col);

        if (_checkWin(row, col, playerValue)) {
            winner = currentPlayer;
            gameState = (currentPlayer == player1) ? GameState.Player1Won : GameState.Player2Won;
            emit GameEnded(gameState, winner);
        } else if (moveCount == 9) {
            gameState = GameState.Draw;
            emit GameEnded(gameState, address(0));
        } else {
            // Switch turns
            currentPlayer = (currentPlayer == player1) ? player2 : player1;
        }
    }

    /**
     * @notice Resets the game board to allow for a new match between the same players.
     * @dev Can only be called by one of the players after a game has concluded.
     */
    function resetGame() external {
        require(gameState != GameState.InProgress, "TicTacToe: Cannot reset a game in progress");
        require(_msgSender() == player1 || _msgSender() == player2, "TicTacToe: Only players can reset the game");

        // Reset board and game variables, keeping the players
        delete board;
        moveCount = 0;
        winner = address(0);

        // Player 1 always starts the new game
        currentPlayer = player1;
        gameState = GameState.InProgress;

        emit GameReset(_msgSender());
        emit GameStarted(player1, player2);
    }

    /**
     * @dev Checks for a win condition based on the last move.
     * @param row The row of the last move.
     * @param col The column of the last move.
     * @param playerValue The value representing the player (1 or 2).
     * @return A boolean indicating if the player has won.
     */
    function _checkWin(uint8 row, uint8 col, uint8 playerValue) private view returns (bool) {
        // Check row
        if (board[row][0] == playerValue && board[row][1] == playerValue && board[row][2] == playerValue) {
            return true;
        }

        // Check column
        if (board[0][col] == playerValue && board[1][col] == playerValue && board[2][col] == playerValue) {
            return true;
        }

        // Check main diagonal (top-left to bottom-right)
        if (row == col) {
            if (board[0][0] == playerValue && board[1][1] == playerValue && board[2][2] == playerValue) {
                return true;
            }
        }

        // Check anti-diagonal (top-right to bottom-left)
        if (row + col == 2) {
            if (board[0][2] == playerValue && board[1][1] == playerValue && board[2][0] == playerValue) {
                return true;
            }
        }

        return false;
    }

    /**
     * @notice Retrieves the current state of the game board.
     * @return A 3x3 array representing the board.
     */
    function getBoard() public view returns (uint8[3][3] memory) {
        return board;
    }

    /**
     * @notice Retrieves comprehensive information about the current game state.
     * @return p1 Address of player 1.
     * @return p2 Address of player 2.
     * @return currentP Address of the current player.
     * @return w Address of the winner (if any).
     * @return state The current GameState.
     */
    function getGameInfo() public view returns (
        address p1,
        address p2,
        address currentP,
        address w,
        GameState state
    ) {
        return (player1, player2, currentPlayer, winner, gameState);
    }
}

